begin;
create function pg_temp.assert_ok(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception '%',message; end if; end $$;
create function pg_temp.expect_error(statement text,expected text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if SQLSTATE=expected then return; end if; raise exception 'Expected %, got %: %',expected,SQLSTATE,SQLERRM; end; raise exception 'Expected failure'; end $$;
insert into auth.users(id) values ('00000000-0000-0000-0000-000000000070'),('00000000-0000-0000-0000-000000000071');
update public.profiles set active=true where id in ('00000000-0000-0000-0000-000000000070','00000000-0000-0000-0000-000000000071');
update public.profiles set role='strategy' where id='00000000-0000-0000-0000-000000000071';
insert into public.events(id,tba_key,year,name,game_slug,created_by) values ('10000000-0000-0000-0000-000000000070','2026notes',2026,'Notes fixture','2026-rebuilt','00000000-0000-0000-0000-000000000071');
insert into public.teams(team_number,tba_team_key) values (7070,'frc7070');
insert into public.event_teams(event_id,team_number) values ('10000000-0000-0000-0000-000000000070',7070);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000070',true);
select pg_temp.expect_error($s$insert into public.team_notes(event_id,team_number,author_user_id,note) values ('10000000-0000-0000-0000-000000000070',7070,auth.uid(),'Scout denied')$s$,'42501');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000071',true);
insert into public.team_notes(event_id,team_number,author_user_id,note) values ('10000000-0000-0000-0000-000000000070',7070,auth.uid(),'Strategy note');
select pg_temp.assert_ok((select count(*)=1 from public.team_notes where team_number=7070),'Strategy note missing');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000070',true);
select pg_temp.assert_ok((select count(*)=1 from public.team_notes where team_number=7070),'Scout cannot read strategy note');
update public.team_notes set note='Scout edit';
select pg_temp.assert_ok((select note='Strategy note' from public.team_notes where team_number=7070),'Scout edited strategy note');
rollback;
